<?php $admin_title='Purchases & Receiving';include '_header.php';
$pdo->exec("CREATE TABLE IF NOT EXISTS purchases(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,reference_no VARCHAR(100) NOT NULL,supplier_id INT UNSIGNED NULL,total DECIMAL(12,2) NOT NULL,notes VARCHAR(255),user_id INT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){if(!csrf_ok($_POST['csrf']??''))$msg='Security token expired.';else{try{$pid=(int)($_POST['product_id']??0);$qty=(int)($_POST['quantity']??0);$sid=(int)($_POST['supplier_id']??0);$cost=(float)($_POST['unit_cost']??0);$ref=trim($_POST['reference_no']??'');$notes=trim($_POST['notes']??'');if(!$pid||$qty<1||$cost<0||$ref==='')throw new Exception('Product, quantity, valid cost and reference are required.');$pdo->beginTransaction();$q=$pdo->prepare('SELECT * FROM products WHERE id=? FOR UPDATE');$q->execute([$pid]);$x=$q->fetch();if(!$x)throw new Exception('Product not found.');$after=(int)$x['quantity']+$qty;$pdo->prepare('UPDATE products SET quantity=?,buying_price=? WHERE id=?')->execute([$after,$cost,$pid]);$total=$qty*$cost;$pdo->prepare('INSERT INTO purchases(reference_no,supplier_id,total,notes,user_id) VALUES(?,?,?,?,?)')->execute([$ref,$sid?:null,$total,$notes,admin_user()['id']??null]);$pdo->prepare('INSERT INTO stock_transactions(product_id,type,quantity,stock_before,stock_after,reason,reference_no,user_id) VALUES(?,?,?,?,?,?,?,?)')->execute([$pid,'IN',$qty,$x['quantity'],$after,'Purchase received',$ref,admin_user()['id']??null]);$pdo->commit();$msg='Purchase received and stock updated successfully.';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$msg=$e->getMessage();}}}
$products=$pdo->query("SELECT id,name,sku,quantity,unit FROM products WHERE status='active' ORDER BY name")->fetchAll();$suppliers=$pdo->query("SELECT id,name FROM suppliers WHERE status='active' ORDER BY name")->fetchAll();$rows=$pdo->query('SELECT p.*,s.name supplier_name,u.name user_name FROM purchases p LEFT JOIN suppliers s ON s.id=p.supplier_id LEFT JOIN users u ON u.id=p.user_id ORDER BY p.id DESC LIMIT 100')->fetchAll();?>
<?php if($msg):?><div class="panel"><b><?=e($msg)?></b></div><?php endif;?><div class="panel"><div class="panel-head"><h2>Receive a Purchase</h2></div><form method="post"><input type="hidden" name="csrf" value="<?=token()?>"><div class="form-grid"><div class="form-group"><label>Product *</label><select class="form-control" name="product_id" required><option value="">Choose product</option><?php foreach($products as $x):?><option value="<?=$x['id']?>"><?=e($x['name'])?> (<?=e($x['sku'])?>) — current: <?=$x['quantity']?> <?=e($x['unit'])?></option><?php endforeach;?></select></div><div class="form-group"><label>Quantity received *</label><input class="form-control" name="quantity" type="number" min="1" required></div><div class="form-group"><label>Supplier</label><select class="form-control" name="supplier_id"><option value="">Select supplier</option><?php foreach($suppliers as $s):?><option value="<?=$s['id']?>"><?=e($s['name'])?></option><?php endforeach;?></select></div><div class="form-group"><label>Unit purchase cost (K) *</label><input class="form-control" name="unit_cost" type="number" min="0" step="0.01" required></div><div class="form-group"><label>Invoice / GRN reference *</label><input class="form-control" name="reference_no" required></div><div class="form-group"><label>Notes</label><input class="form-control" name="notes"></div></div><p><button class="btn btn-primary">Confirm Goods Received</button></p><small class="muted">A purchase record alone is not stock. This form increases stock because goods are being confirmed as received.</small></form></div><div class="panel"><div class="panel-head"><h2>Purchase History</h2></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Reference</th><th>Supplier</th><th>Total Cost</th><th>Notes</th><th>Recorded by</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['reference_no'])?></td><td><?=e($r['supplier_name'])?></td><td>K<?=number_format($r['total'],2)?></td><td><?=e($r['notes'])?></td><td><?=e($r['user_name'])?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6">No purchases recorded.</td></tr><?php endif;?></tbody></table></div></div><?php include '_footer.php';?>